MP = {'酸素': (-219, -183), '窒素': (-210, -196), 'エタノール': (-115, 78), '水': (0, 100), '鉄': (1538, 2862), 'アルミニウム': (660, 2467), '水銀': (-39, 357)}

def tc(x):
    """温度の表示（負の数は全角のマイナス）"""
    return str(x).replace('-', '−')

def state(name, t):
    mp, bp = MP[name]
    return '固体' if t < mp else '液体' if t < bp else '気体'

